// leadership, big matches, derbies, cups, Europe, international duty, decisive moments,
// transfers, contracts, agents, money, sponsors, press, social media, supporters,
// rivalries, injuries, health, mental load, superstitions, daily club life, travel,
// the calendar, refereeing, youth, stardom, trophies, the veteran years and retirement.
// They are split into several arrays because Swift type-checks one huge literal far more
// slowly than several moderate ones.

